import { mapState } from "vuex";
import timeOptions from "@/utils/timeOptions";
import { getApplyList, getVerifyForm, getMarkForm } from "@/api/supplier";
export default {
	data(){
		return{
			loading: false, 
			options: timeOptions,
			timeVal: [],
			formValidate:{
				page: 1,
				limit: 20,
				data:'',
				status:'',
				keyword:''
			},
			total:0,
			tableList:[],
			columns: [
			  {
			    title: "ID",
			    key: "id",
			    width: 80,
			  },
			  {
			    title: "供应商名称",
			    key: "system_name",
			    minWidth: 150,
			  },
			  {
			    title: "联系人姓名",
			    key: "name",
			    minWidth: 90,
			  },
			  {
			    title: "联系方式",
			    key: "phone",
			    minWidth: 90,
			  },
			  {
			    title: "申请时间",
			    key: "add_time",
			    minWidth: 150,
			  },
			  {
			    title: "资质图片",
			    slot: "images",
			    minWidth: 200,
			  },
			  {
			    title: "状态",
			    slot: "status",
			    minWidth: 100,
			  },
			  {
			    title: "备注",
			    slot: "mark",
			    minWidth: 100,
			  },
			  {
			    title: "操作",
			    slot: "action",
			    fixed: "right",
			    width: 140,
			  },
			],
		}
	},
	computed: {
	  ...mapState("admin/layout", ["isMobile"]),
	  labelWidth() {
	    return this.isMobile ? undefined : 96;
	  },
	  labelPosition() {
	    return this.isMobile ? "top" : "right";
	  },
	},
	created(){
		this.getList();
	},
	mounted(){},
	methods:{
		verify(row){
			this.$modalForm(getVerifyForm(row.id)).then(() => this.getList());
		},
		mask(row){
			this.$modalForm(getMarkForm(row.id)).then(() => this.getList());
		},
		// 删除
		del (row, tit, num) {
		    let delfromData = {
		        title: tit,
		        num: num,
		        url: `/supplier/apply/del/${row.id}`,
		        method: 'DELETE',
		        ids: ''
		    };
		    this.$modalSure(delfromData).then((res) => {
		        this.$Message.success(res.msg);
		        this.tableList.splice(num, 1);
		        if (!this.tableList.length) {
		          this.formValidate.page =
		              this.formValidate.page == 1 ? 1 : this.formValidate.page - 1;
		        }
		        this.getList();
		    }).catch(res => {
		        this.$Message.error(res.msg);
		    });
		},
		userSearchs(){
			this.formValidate.page = 1;
			this.getList();
		},
		reset(){
			this.formValidate = {
			  page: 1,
			  limit: 20,
			  data:'',
			  status:'',
			  keyword:''
			};
			this.timeVal = [];
			this.getList();
		},
		pageChange (index) {
		    this.formValidate.page = index;
		    this.getList();
		},
		// 具体日期
		onchangeTime(e) {
		  this.timeVal = e;
		  this.formValidate.data = this.timeVal[0] ? this.timeVal.join("-") : "";
		  this.formValidate.page = 1;
		  this.getList();
		},
		getList(){
			getApplyList(this.formValidate).then(res=>{
				let data = res.data;
				this.tableList = data.list;
				this.total = data.count;
			}).catch(err=>{
				this.$Message.error(err.msg);
			})
		}
	}
}
